        "anchor": "yields_high",
        "text": "这是本期最需要按尺度拆开读的一处，也是过去三周里这条腿第一次**真正归位**。**周线**：10Y 5.12→**4.92%**(-20bp)、2Y **4.63%**(-20bp)、30Y -16.6bp、TLT 周 **+2.44%**——**两端同步下行**，是平行下移而不是熊平/牛陡的某一种。**月线**：10Y **-4bp**(上周 +2bp、上上周 -34bp)。所以 price_split 的 yldUp 仍判 F，但这次 F 的含义是**「债在涨」**，而不是 11-19 那期的「月线刚好没跌够 5bp」。**同一个 ID、三种语义、连续三期**——这是本面板第五次遇到「锚状态不变而语义完全不同」(前四次是 yields_high 的贴顶未创高、cpi_accel 的锚 off 而 3 月年化上升、信用的周线/月线背离、yldUp 的月线阈值)。★ 本期真正的新东西在**构成**：上周 26bp 的上行里 TIPS +29bp、BEI -1bp(纯折现率)；本周 -20bp 里 TIPS **-13bp**、BEI **-9bp**。**BEI 第一次贡献了接近一半**，而 BEI 现在在 **0 分位**(2.12%、月 -22bp)。这意味着债市买的不只是「利率会降」，还包括「通胀会掉」——那是衰退定价，不是折现率定价。★ 三个必须给的数：① yldUp 翻 T 需 10Y 月变化 > +5bp，等价于 10Y ≥ **5.01**，距现价 **9bp**(上周只差 3bp，方向本来对了，本周反向)；② yields_high 阈值 5.305，距 **39bp**(上周 19bp，重新拉开)；③ 若两者同时翻转，price_split 掉到 2/3、real_rate_shock 以 3/3 接管、情景②的 yields_high 腿同时转 on。★ **为什么这构成「矛盾」**：如果这是通缩/衰退定价，股票该跌(已跌 -6.20%)、信用该阔(已阔 +25bp)、黄金该涨——**而黄金跌了 5.79%**。三条里两条对上、一条完全反向，说明当前定价不是单一叙事，而是「增长与通胀的预期在下修」+「抵押品在被抛售」两件事同时发生。"
